            case "humidity":
                ret.put("sensor", "humidity");
                ret.put("value", 65.0);
                ret.put("unit", "%");
                call.resolve(ret);
                break;
            case "battery":
                ret.put("sensor", "battery");
                ret.put("value", 87.0);
                ret.put("unit", "%");
                call.resolve(ret);
                break;
            default:
                call.reject("Unsupported sensor: " + sensor);
                break;
        }
    }

    @PluginMethod
    public void isAvailable(PluginCall call) {
        String sensor = call.getString("sensor");
        JSObject ret = new JSObject();
        if (sensor == null) {
            ret.put("available", false);
            call.resolve(ret);
            return;
        }

        switch (sensor) {
            case "temperature":
            case "humidity":
            case "battery":
                ret.put("available", true);
                break;
            default:
                ret.put("available", false);
                break;
